import React,{useCallback,useEffect,useMemo,useRef,useState} from 'react';


function EventForm({onSubmit,event}){const dt=event?.startsAt?new Date(new Date(event.startsAt).getTime()-new Date(event.startsAt).getTimezoneOffset()*60000).toISOString().slice(0,16):'';return <div className="form-modal"><span className="eyebrow green-text">{event?.status==='Publicado'?'EDIÇÃO DO CALENDÁRIO':event?'AJUSTE DE CONTEÚDO':'NOVO CONTEÚDO · RASCUNHO'}</span><h2>{event?.status==='Publicado'?'Editar evento publicado':event?'Revise o rascunho.':'Cadastre um evento.'}</h2><p>{event?.status==='Publicado'?'A alteração aparece na agenda pública e gera um registro de atualização.':event?'Atualize as informações devolvidas pela revisão.':'Depois de salvar, você poderá enviar o rascunho à fila de aprovação.'}</p><form className="event-form" onSubmit={onSubmit}><label>Título do evento<input name="title" placeholder="Ex.: Festival de Cultura Guamaense" defaultValue={event?.title||''} required/></label><label>Descrição<textarea name="description" placeholder="Conte o que o público precisa saber" defaultValue={event?.description||''}/></label><div className="form-row"><label>Categoria<select name="category" defaultValue={event?.category||'Cultura'}><option>Cultura</option><option>Esporte</option><option>Lazer</option></select></label><label>Data e horário<input name="startsAt" type="datetime-local" defaultValue={dt} required/></label></div><label>Local<input name="location" placeholder="Praça, estádio ou endereço" defaultValue={event?.location||''} required/></label><div className="form-row"><label>Faixa etária<input name="ageRange" defaultValue={event?.ageRange||'Livre'}/></label><label>Vagas<input name="capacity" type="number" min="0" defaultValue={event?.capacity??100}/></label></div><label>Regra de bebida<input name="drinkRule" defaultValue={event?.drinkRule||'Não informado'}/></label><div className="form-row"><label>Organizador<select name="organizerType" defaultValue={event?.organizerType||'Prefeitura'}><option>Prefeitura</option><option>SECELT</option><option>Privado</option></select></label><label className="checkbox-line"><input name="isFree" type="checkbox" defaultChecked={event?!!event.isFree:true}/> Evento gratuito</label></div><div className="form-actions"><button type="button" className="button outline" onClick={()=>document.dispatchEvent(new Event('close-dialog'))}>Cancelar</button><Button type="submit">{event?'Salvar ajustes':'Salvar rascunho'} <ChevronRight size={15}/></Button></div></form></div>}
import {createRoot} from 'react-dom/client';
import {Home, Trophy, CalendarDays, MapPin, Menu, ChevronLeft, ChevronRight, ArrowUpRight, ExternalLink, Clock3, BadgeCheck, LayoutDashboard, FileText, Users, Activity, Plus, Pencil, Check, X, Search, LogOut, Bell, RefreshCw, ShieldCheck, QrCode, Map, Newspaper, SlidersHorizontal, Sun, Moon} from 'lucide-react';
import {QRCodeSVG} from 'qrcode.react';
import './style.css';
import {LiquidGlass} from '@ybouane/liquidglass';
import './liquid-design.css';
import './theme-modes.css';
import './refined-ui.css';
import './experience-system.css';

const ICONS={home:Home,sports:Trophy,events:CalendarDays,tourism:MapPin};
const glassConfig=(theme='light',kind='panel')=>JSON.stringify({blurAmount:.2,refraction:kind==='nav'?1.08:.9,chromAberration:.035,edgeHighlight:.72,specular:.72,fresnel:1,distortion:.055,cornerRadius:kind==='nav'?30:kind==='hero'?18:kind==='sheet'?26:20,zRadius:kind==='water'?34:kind==='nav'?20:16,opacity:kind==='nav'?(theme==='dark'?.64:.84):kind==='sheet'?(theme==='dark'?.74:.88):(theme==='dark'?.64:.84),saturation:.18,tintStrength:theme==='dark'?.2:.1,brightness:theme==='dark'?.015:.035,shadowOpacity:.24,shadowSpread:14,shadowOffsetY:6,button:true});
const fmtDate=(v,opts={day:'2-digit',month:'short'})=>v?new Intl.DateTimeFormat('pt-BR',opts).format(new Date(v)):'';
const fmtDateTime=v=>v?new Intl.DateTimeFormat('pt-BR',{day:'2-digit',month:'short',year:'numeric',hour:'2-digit',minute:'2-digit'}).format(new Date(v)):'';
function dayKey(value){const d=value instanceof Date?value:new Date(value);const parts=new Intl.DateTimeFormat('en-GB',{timeZone:'America/Sao_Paulo',year:'numeric',month:'2-digit',day:'2-digit'}).formatToParts(d);const part=t=>parts.find(p=>p.type===t)?.value;return `${part('year')}-${part('month')}-${part('day')}`}
function mapHref(point){const params=new URLSearchParams({api:'1',query:[point.name,point.address].filter(Boolean).join(', ')});if(point.placeId)params.set('query_place_id',point.placeId);else if(point.latitude&&point.longitude)params.set('query',`${point.latitude},${point.longitude}`);return `https://www.google.com/maps/search/?${params.toString()}`}
const api=async(path,{token,...options}={})=>{const res=await fetch('/api'+path,{...options,headers:{'Content-Type':'application/json',...(token?{Authorization:`Bearer ${token}`} :{}),...(options?.headers||{})}});const data=await res.json().catch(()=>({}));if(!res.ok)throw Error(data.error||'Não foi possível concluir esta ação.');return data};
function BrandMark({className=''}){return <span className={`brand-symbol ${className}`} aria-hidden="true"><svg viewBox="0 0 64 64"><path d="M13 35c7-11 14-11 20 0s12 11 19-1"/><path className="brand-wave" d="M15 44c5-6 9-6 14 0"/><circle cx="48" cy="18" r="3.5"/></svg></span>}
function Art({kind='river',className=''}){return <div className={`art ${kind} ${className}`} aria-label="Arte gráfica autoral com formas inspiradas na paisagem local"><span className="sun"/>{kind.includes('hero-land')&&<span className="water-orb" aria-hidden="true"/>}<span className="hill h1"/><span className="hill h2"/><span className="river"/><span className="art-label" aria-hidden="true"/></div>}
function Button({children,kind='blue',glass=false,theme='light',...props}){const className=`button ${kind}${glass?' glass-action liquid-target':''}`;return glass?<button className={className} data-config={glassConfig(theme,'hero')} {...props}>{children}</button>:<button className={className} {...props}>{children}</button>}
function App(){const glassInstances=useRef([]);const [page,setPage]=useState(location.hash==='#admin'?'admin':'home');const [theme,setTheme]=useState(()=>localStorage.getItem('secelt-theme')==='dark'?'dark':'light');const [token,setToken]=useState(localStorage.getItem('secelt-token')||'');const [user,setUser]=useState(null);const [events,setEvents]=useState([]);const [sports,setSports]=useState({competitions:[],teams:[],matches:[],members:[]});const [places,setPlaces]=useState([]);const [googlePhotosEnabled,setGooglePhotosEnabled]=useState(false);const [adminPlaces,setAdminPlaces]=useState([]);const [news,setNews]=useState([]);const [overview,setOverview]=useState({pending:0,published:0,activeUsers:0,registrations:0});const [adminEvents,setAdminEvents]=useState([]);const [modal,setModal]=useState(null);const [loading,setLoading]=useState(true);const [toast,setToast]=useState('');const [competition,setCompetition]=useState('');const [search,setSearch]=useState('');
const notify=msg=>{setToast(msg);setTimeout(()=>setToast(''),2800)};
useEffect(()=>{document.documentElement.dataset.theme=theme;localStorage.setItem('secelt-theme',theme)},[theme]);
useEffect(()=>{let cancelled=false;const instances=[];const groups=[['.bottom-nav','.bottom-nav-glass'],['.quick-grid','.quick-card'],['.stat-grid','.stat-card'],['.modal-scrim','.event-modal']];(async()=>{for(const [rootSelector,targetSelector] of groups){const root=document.querySelector(rootSelector);if(!root)continue;const glassElements=[...root.querySelectorAll(targetSelector)].filter(el=>el.parentElement===root);if(!glassElements.length)continue;try{const instance=await LiquidGlass.init({root,glassElements});if(cancelled)instance.destroy();else instances.push(instance)}catch(error){glassElements.forEach(el=>el.classList.add('liquid-fallback'));console.warn('Efeito liquid glass indisponível; usando acabamento visual alternativo.',error)}}})();return()=>{cancelled=true;instances.forEach(instance=>instance.destroy());glassInstances.current=[]}},[page,theme,modal?.type,user?.role,loading,events.length,news.length,places.length,adminEvents.length,adminPlaces.length,overview.pending,overview.published]);
useEffect(()=>{document.body.classList.add('motion-ready');const targets=document.querySelectorAll('.quick-card,.feature,.news-card,.panel,.event-row,.place-card,.admin-panel,.stat-card');const observer='IntersectionObserver' in window?new IntersectionObserver(entries=>entries.forEach(entry=>{if(entry.isIntersecting){entry.target.classList.add('is-inview');observer.unobserve(entry.target)}}),{threshold:.12,rootMargin:'0px 0px -6% 0px'}):null;targets.forEach((el,index)=>{el.classList.add('reveal-on-scroll');el.style.setProperty('--reveal-index',Math.min(index,6));observer?.observe(el);if(!observer)el.classList.add('is-inview')});let frame=0;const update=()=>{if(frame)return;frame=requestAnimationFrame(()=>{const max=Math.max(1,document.documentElement.scrollHeight-window.innerHeight);document.documentElement.style.setProperty('--scroll-progress',`${Math.min(100,Math.max(0,window.scrollY/max*100))}%`);frame=0})};update();window.addEventListener('scroll',update,{passive:true});return()=>{observer?.disconnect();window.removeEventListener('scroll',update);if(frame)cancelAnimationFrame(frame);targets.forEach(el=>{el.classList.remove('reveal-on-scroll','is-inview');el.style.removeProperty('--reveal-index')})}},[page,loading,news.length,events.length,places.length,adminEvents.length,adminPlaces.length]);
 useEffect(()=>{const targets=[...document.querySelectorAll('.liquid-target')];const move=e=>{const el=e.currentTarget,r=el.getBoundingClientRect(),x=(e.clientX-r.left)/Math.max(r.width,1),y=(e.clientY-r.top)/Math.max(r.height,1);el.style.setProperty('--touch-x',`${e.clientX-r.left}px`);el.style.setProperty('--touch-y',`${e.clientY-r.top}px`);el.style.setProperty('--tilt-x',`${(0.5-y)*3.2}deg`);el.style.setProperty('--tilt-y',`${(x-0.5)*3.2}deg`)};const leave=e=>{e.currentTarget.style.setProperty('--tilt-x','0deg');e.currentTarget.style.setProperty('--tilt-y','0deg')};const press=e=>{move(e);const el=e.currentTarget;el.classList.remove('liquid-touch');void el.offsetWidth;el.classList.add('liquid-touch');window.setTimeout(()=>el.classList.remove('liquid-touch'),860)};targets.forEach(el=>{el.addEventListener('pointermove',move);el.addEventListener('pointerleave',leave);el.addEventListener('pointerdown',press)});return()=>targets.forEach(el=>{el.removeEventListener('pointermove',move);el.removeEventListener('pointerleave',leave);el.removeEventListener('pointerdown',press)})},[page,theme,modal?.type,user?.role,loading,news.length,events.length,places.length,adminEvents.length,adminPlaces.length]);
 const loadPublic=useCallback(async()=>{setLoading(true);try{const [e,s,t,n]=await Promise.all([api('/events'),api('/sports'),api('/tourism'),api('/news')]);setEvents(e.items);setSports(s);setPlaces(t.items);setGooglePhotosEnabled(!!t.googlePhotosEnabled);setNews(n.items);setCompetition(s.competitions[0]?.id||'')}catch(e){notify(e.message)}finally{setLoading(false)}},[]);
 const loadAdmin=useCallback(async(t=token)=>{if(!t)return;try{const [o,e,placesData]=await Promise.all([api('/admin/overview',{token:t}),api('/admin/events',{token:t}),api('/admin/tourism',{token:t})]);setOverview(o);setAdminEvents(e.items);setAdminPlaces(placesData.items)}catch(e){if(/Entre na área/.test(e.message)){localStorage.removeItem('secelt-token');setToken('');setUser(null)}notify(e.message)}},[token]);
useEffect(()=>{loadPublic()},[loadPublic]);useEffect(()=>{if(token){api('/auth/me',{token}).then(d=>{setUser(d.user);loadAdmin(token)}).catch(()=>{localStorage.removeItem('secelt-token');setToken('')})}},[]);
useEffect(()=>{if(page==='admin'&&token)loadAdmin()},[page,token,loadAdmin]);useEffect(()=>{document.title=`${page==='admin'?'Painel · ':''}SECELT Conecta`;window.scrollTo(0,0);location.hash=page==='admin'?'admin':''},[page]);
const login=async(e)=>{e.preventDefault();const f=new FormData(e.currentTarget);try{const d=await api('/auth/login',{method:'POST',body:JSON.stringify({email:f.get('email'),password:f.get('password')})});localStorage.setItem('secelt-token',d.token);setToken(d.token);setUser(d.user);setPage('admin');notify(`Bem-vinda, ${d.user.name.split(' ')[0]}.`);setModal(null);loadAdmin(d.token)}catch(e){notify(e.message)}};
const logout=async()=>{await api('/auth/logout',{method:'POST',token}).catch(()=>{});localStorage.removeItem('secelt-token');setToken('');setUser(null);setPage('home');notify('Sessão encerrada.')};
 const changeStatus=async(id,status)=>{try{await api(`/admin/events/${id}/status`,{method:'PATCH',token,body:JSON.stringify({status})});notify(status==='Publicado'?'Evento publicado na agenda.':'Status do evento atualizado.');await loadAdmin();await loadPublic()}catch(e){notify(e.message)}};
 const saveEvent=async(e)=>{e.preventDefault();const f=new FormData(e.currentTarget);const body={title:f.get('title'),description:f.get('description'),category:f.get('category'),startsAt:new Date(f.get('startsAt')).toISOString(),location:f.get('location'),ageRange:f.get('ageRange'),drinkRule:f.get('drinkRule'),organizerType:f.get('organizerType'),isFree:f.get('isFree')==='on',capacity:Number(f.get('capacity'))};const wasPublished=selectedAdminEvent?.status==='Publicado';try{if(modal?.type==='edit-event')await api('/admin/events/'+modal.id,{method:'PUT',token,body:JSON.stringify(body)});else await api('/admin/events',{method:'POST',token,body:JSON.stringify(body)});setModal(null);notify(modal?.type==='edit-event'?(wasPublished?'Calendário atualizado e nota publicada no feed.':'Ajustes salvos no rascunho.'):'Rascunho salvo. Envie para aprovação quando estiver pronto.');await loadAdmin();await loadPublic()}catch(e){notify(e.message)}};
 const savePlace=async(e)=>{e.preventDefault();const f=new FormData(e.currentTarget);const body={name:f.get('name'),description:f.get('description'),category:f.get('category'),address:f.get('address'),imageUrl:f.get('imageUrl'),placeId:f.get('placeId'),latitude:f.get('latitude'),longitude:f.get('longitude')};try{if(modal?.type==='edit-place')await api(`/admin/tourism/${modal.id}`,{method:'PUT',token,body:JSON.stringify(body)});else await api('/admin/tourism',{method:'POST',token,body:JSON.stringify(body)});setModal(null);notify('Ponto turístico salvo como rascunho.');await loadAdmin()}catch(e){notify(e.message)}};
 const changePlaceStatus=async(id,status)=>{try{await api(`/admin/tourism/${id}/status`,{method:'PATCH',token,body:JSON.stringify({status})});notify(status==='Publicado'?'Ponto turístico publicado.':'Status do local atualizado.');await loadAdmin();await loadPublic()}catch(e){notify(e.message)}};
 const saveUser=async(e)=>{e.preventDefault();const f=new FormData(e.currentTarget);try{await api('/admin/users',{method:'POST',token,body:JSON.stringify({name:f.get('name'),email:f.get('email'),password:f.get('password'),role:f.get('role')})});setModal(null);notify('Conta de servidor criada com sucesso.');loadAdmin()}catch(e){notify(e.message)}};
 const selectedEvent=modal?.type==='event'?events.find(e=>e.id===modal.id):null;const selectedAdminEvent=modal?.type==='edit-event'?adminEvents.find(e=>e.id===modal.id):null;const selectedAdminPlace=modal?.type==='edit-place'?adminPlaces.find(p=>p.id===modal.id):null;
 return <div className="shell"><header className="topbar"><button className="brand" onClick={()=>setPage('home')}><BrandMark/><span><b>SECELT</b><small>Conecta</small></span></button><div className="top-right"><span className="official"><i/>Agenda e informações</span><button className="theme-toggle" onClick={()=>setTheme(theme==='dark'?'light':'dark')} aria-label={theme==='dark'?'Ativar tema claro':'Ativar tema escuro'} title={theme==='dark'?'Tema claro':'Tema escuro'}>{theme==='dark'?<Sun size={16}/>:<Moon size={16}/>}</button><button className="admin-entry" aria-label="Área administrativa" title="Área administrativa" onClick={()=>token?setPage('admin'):setModal({type:'login'})}><LayoutDashboard size={14}/>{token?'Painel administrativo':'Área administrativa'}</button></div></header>
 {page==='home'&&<HomePage setPage={setPage} news={news} events={events} loading={loading} theme={theme}/>}
{page==='sports'&&<SportsPage sports={sports} competition={competition} setCompetition={setCompetition}/>}
{page==='events'&&<EventsPage events={events} loading={loading} search={search} setSearch={setSearch} onOpen={id=>setModal({type:'event',id})}/>}
 {page==='tourism'&&<TourismPage places={places} googlePhotosEnabled={googlePhotosEnabled}/>}
 {page==='admin'&&(user?<AdminPage theme={theme} user={user} overview={overview} events={adminEvents} places={adminPlaces} onCreate={()=>setModal({type:'new-event'})} onCreatePlace={()=>setModal({type:'new-place'})} onCreateUser={()=>setModal({type:'new-user'})} onEdit={id=>setModal({type:'edit-event',id})} onEditPlace={id=>setModal({type:'edit-place',id})} onStatus={changeStatus} onPlaceStatus={changePlaceStatus} onLogout={logout} onRefresh={()=>loadAdmin()}/>:<LoginPage onSubmit={login}/>) }
{page!=='admin'&&<BottomNav page={page} setPage={setPage} theme={theme}/>}
{modal?.type==='login'&&<Modal theme={theme} onClose={()=>setModal(null)}><LoginForm onSubmit={login}/></Modal>}
 {modal?.type==='event'&&selectedEvent&&<Modal theme={theme} onClose={()=>setModal(null)}><EventDetails event={selectedEvent} onRegister={async(name,email)=>{try{const d=await api(`/events?id=${selectedEvent.id}`,{method:'POST',body:JSON.stringify({name,email})});setModal({type:'ticket',qr:d.qrCode,event:selectedEvent});loadPublic()}catch(e){notify(e.message)}}}/></Modal>}
{modal?.type==='ticket'&&<Modal theme={theme} onClose={()=>setModal(null)}><Ticket event={modal.event} qr={modal.qr}/></Modal>}
{modal?.type==='new-event'&&<Modal theme={theme} onClose={()=>setModal(null)}><EventForm onSubmit={saveEvent}/></Modal>}
{modal?.type==='edit-event'&&selectedAdminEvent&&<Modal theme={theme} onClose={()=>setModal(null)}><EventForm event={selectedAdminEvent} onSubmit={saveEvent}/></Modal>}
 {['new-place','edit-place'].includes(modal?.type)&&<Modal theme={theme} onClose={()=>setModal(null)}><PlaceForm key={modal.type==='edit-place'?modal.id:'new'} event={selectedAdminPlace} token={token} onSubmit={savePlace} googlePhotosEnabled={googlePhotosEnabled}/></Modal>}
{modal?.type==='new-user'&&<Modal theme={theme} onClose={()=>setModal(null)}><UserForm onSubmit={saveUser}/></Modal>}
{toast&&<div role="status" className="toast show">{toast}</div>}
</div>}
function BottomNav({page,setPage,theme}){return <nav className="bottom-nav" aria-label="Seções principais"><span className="liquid-scene nav-scene" aria-hidden="true"/><div className="bottom-nav-glass liquid-target" data-config={glassConfig(theme,'nav')}>{[['home','Início'],['sports','Esporte'],['events','Eventos'],['tourism','Turismo']].map(([key,label])=>{const Icon=ICONS[key];return <button key={key} className={page===key?'active':''} aria-current={page===key?'page':undefined} onClick={()=>setPage(key)}><Icon size={20}/>{label}</button>})}</div></nav>}
function HomePage({setPage,news,events,loading,theme}) {
 const nextEvent=[...events].filter(e=>e.status==='Publicado'&&new Date(e.startsAt)>=new Date()).sort((a,b)=>new Date(a.startsAt)-new Date(b.startsAt))[0];
 const updated=events.reduce((a,e)=>!a||e.updatedAt>a?e.updatedAt:a,'');
 const quick=[['sports','Esporte','Competições e resultados',Trophy],['events','Eventos','Calendário e inscrições',CalendarDays],['tourism','Turismo','Lugares e como chegar',MapPin]];
 return <>
  <section className="hero home-hero">
   <div className="hero-copy"><span className="eyebrow"><i/>SECELT CONECTA</span><h1>Agenda e vida<br/>pública em <em>um lugar.</em></h1><p>Consulte eventos, resultados esportivos e pontos turísticos.</p><Button kind="light" theme={theme} onClick={()=>setPage('events')}>Abrir calendário <ArrowUpRight size={16}/></Button>
    <div className="hero-next">{nextEvent?<><span className="next-date">{fmtDate(nextEvent.startsAt,{day:'2-digit',month:'short'}).toUpperCase()}</span><span><small>PRÓXIMO EVENTO</small><b>{nextEvent.title}</b></span></>:<span><small>CALENDÁRIO OFICIAL</small><b>Ainda não há eventos publicados.</b></span>}</div>
   </div>
   <div className="hero-photo"><img src="/assets/tourism-river.jpg" alt="Rio Guamá ao pôr do sol"/><span className="photo-credit"><a href="https://commons.wikimedia.org/wiki/File:P%C3%B4r_do_Sol_em_S%C3%A3o_Miguel_do_Guama_-_panoramio.jpg" target="_blank" rel="noreferrer">Rio Guamá · Guilherme J. Corrêa</a> · <a href="https://creativecommons.org/licenses/by-sa/3.0/" target="_blank" rel="noreferrer">CC BY-SA 3.0</a></span></div>
  </section>
  <section className="quick section-wrap"><div className="section-heading"><div><span className="eyebrow muted">ACESSO RÁPIDO</span><h2>O que você procura?</h2></div></div><div className="quick-grid"><span className="liquid-scene tile-scene" aria-hidden="true"/>{quick.map(([p,t,sub,I])=><button type="button" className={'quick-card liquid-target '+p+'-card'} data-config={glassConfig(theme,'tile')} key={p} onClick={()=>setPage(p)}><span className="quick-icon"><I size={20}/></span><span><small>{sub}</small><b>{t}</b></span><ArrowUpRight className="arrow" size={16}/></button>)}</div></section>
  <section className="feature sports-feature section-wrap"><div className="feature-image"><img src="/assets/sports-field.jpg" alt="Campo e arquibancada esportiva"/><span className="photo-credit"><a href="https://commons.wikimedia.org/wiki/File:DZ6_2354_Empty_bleachers_and_a_covered_grandstand_overlook_a_quiet_artificial-turf_sports_field_at_dusk.jpg" target="_blank" rel="noreferrer">Foto: PattayaPatrol</a> · <a href="https://creativecommons.org/licenses/by-sa/4.0/" target="_blank" rel="noreferrer">CC BY-SA 4.0</a></span></div><div className="feature-text"><span className="eyebrow green-text">ESPORTE</span><h2>Jogos<br/><em>Guamaenses 2026</em></h2><p>Consulte a classificação, os próximos confrontos e os resultados publicados.</p><button className="text-link" onClick={()=>setPage('sports')}>Ver competições <span>→</span></button></div></section>
  <section className="news-section"><div className="section-wrap"><div className="section-heading"><div><span className="eyebrow muted">ATUALIZAÇÕES</span><h2>Publicações recentes</h2></div><button className="text-link" onClick={()=>setPage('events')}>Abrir agenda →</button></div><div className="news-grid">{loading?<p>Carregando atualizações…</p>:news.length?news.slice(0,4).map(n=>{const sport=n.category==='Esporte';return <article className="news-card" key={n.id}><div className="news-art"><img src={sport?'/assets/sports-field.jpg':'/assets/culture-stage.jpg'} alt={sport?'Campo esportivo':'Apresentação musical'}/><small className="photo-credit">{sport?<><a href="https://commons.wikimedia.org/wiki/File:DZ6_2354_Empty_bleachers_and_a_covered_grandstand_overlook_a_quiet_artificial-turf_sports_field_at_dusk.jpg" target="_blank" rel="noreferrer">Foto: PattayaPatrol</a> · <a href="https://creativecommons.org/licenses/by-sa/4.0/" target="_blank" rel="noreferrer">CC BY-SA 4.0</a> · imagem de referência</>:<><a href="https://commons.wikimedia.org/wiki/File:Festival_internacional_de_musica_do_par%C3%A1_-_panoramio.jpg" target="_blank" rel="noreferrer">Foto: Roberto de Vasconcelos</a> · <a href="https://creativecommons.org/licenses/by-sa/3.0/" target="_blank" rel="noreferrer">CC BY-SA 3.0</a> · imagem de referência</>}</small></div><div className="news-meta"><span>{n.category}</span><span>atualizado {fmtDateTime(n.updatedAt)}</span></div><h3>{n.title}</h3><p>{n.body}</p><button className="text-link" onClick={()=>setPage(sport?'sports':'events')}>Ver publicação <span>→</span></button></article>}):<p className="empty-state">Ainda não há atualizações publicadas.</p>}</div></div></section>
  <section className="update-strip"><span className="update-symbol"><RefreshCw size={15}/></span><span><small>CALENDÁRIO OFICIAL</small><b>{updated?'Última atualização: '+fmtDateTime(updated):'Aguardando a primeira publicação'}</b></span><button className="text-link" onClick={()=>setPage('events')}>Ver agenda →</button></section>
  <footer className="footer"><span className="footer-brand">SECELT <b>Conecta</b></span><span>Esporte · eventos · turismo</span><span>São Miguel do Guamá · PA</span></footer>
 </>;
}
function SportsPage({sports,competition,setCompetition}){const comp=sports.competitions.find(c=>c.id===competition);const teams=sports.teams.filter(t=>t.competitionId===competition);const matches=sports.matches.filter(m=>m.competition===comp?.name);const activeMatches=matches.filter(m=>m.status==='Encerrada');const standings=teams.map(t=>({...t,played:activeMatches.filter(m=>m.homeTeam===t.name||m.awayTeam===t.name).length,wins:activeMatches.filter(m=>(m.homeTeam===t.name&&m.homeScore>m.awayScore)||(m.awayTeam===t.name&&m.awayScore>m.homeScore)).length}));return <><div className="page-banner sports-banner"><div className="sports-banner-copy"><span className="eyebrow">COMPETIÇÕES</span><h1>Resultados<br/><em>e equipes.</em></h1><p>Classificação, partidas e elencos cadastrados.</p></div><div className="sports-banner-photo"><img src="/assets/sports-field.jpg" alt="Campo esportivo"/><small className="photo-credit"><a href="https://commons.wikimedia.org/wiki/File:DZ6_2354_Empty_bleachers_and_a_covered_grandstand_overlook_a_quiet_artificial-turf_sports_field_at_dusk.jpg" target="_blank" rel="noreferrer">Foto: PattayaPatrol</a> · <a href="https://creativecommons.org/licenses/by-sa/4.0/" target="_blank" rel="noreferrer">CC BY-SA 4.0</a></small></div></div><section className="section-wrap content-section"><div className="tabs">{sports.competitions.map(c=><button key={c.id} className={competition===c.id?'selected':''} onClick={()=>setCompetition(c.id)}>{c.name}</button>)}</div><div className="sport-layout"><article className="panel standings"><div className="panel-head"><div><span className="eyebrow muted">EDIÇÃO {comp?.edition}</span><h2>Tabela de classificação</h2></div><span className="live-tag">● {comp?.status?.toUpperCase()}</span></div><div className="table-scroll"><table><thead><tr><th>CLUBE</th><th>P</th><th>V</th><th>SG</th></tr></thead><tbody>{standings.map((t,i)=><tr key={t.id}><td><span className="rank">0{i+1}</span><b>{t.name}</b></td><td>{t.points}</td><td>{t.wins}</td><td>{t.goalDifference>0?'+':''}{t.goalDifference}</td></tr>)}</tbody></table></div><small className="sport-note">P pontos · V vitórias · SG saldo de gols</small></article><article className="panel next-panel"><span className="eyebrow muted">PRÓXIMO CONFRONTO</span>{matches.find(m=>m.status==='Agendada')?<MatchFeature match={matches.find(m=>m.status==='Agendada')}/>:<p>Não há partidas futuras cadastradas.</p>}</article></div><div className="section-heading subheading"><div><span className="eyebrow muted">ÚLTIMOS RESULTADOS</span><h2>O jogo continua.</h2></div><span className="index">PLACARES OFICIAIS</span></div><div className="results">{activeMatches.map(m=><div className="result-row" key={m.id}><span>{fmtDate(m.startsAt,{day:'2-digit',month:'short'}).toUpperCase()} · {new Date(m.startsAt).toLocaleTimeString('pt-BR',{hour:'2-digit',minute:'2-digit'})}</span><b>{m.homeTeam}</b><strong>{m.homeScore} — {m.awayScore}</strong><b>{m.awayTeam}</b><span className="final-tag">ENCERRADO</span></div>)}</div><div className="sport-note">Temporada {comp?.edition} · {comp?.name}</div><h3 className="roster-title">Elenco em destaque</h3><div className="roster-grid">{sports.members.filter(m=>m.teamId===teams[0]?.id).map(m=><article className="roster-card" key={m.id}><span>{m.shirtNumber??'SEC'}</span><b>{m.name}</b><small>{m.role}</small></article>)}</div></section></>}
function MatchFeature({match}){return <><div className="versus"><div><span className="team-badge">{match.homeTeam[0]}</span><b>{match.homeTeam}</b></div><span>VS</span><div><span className="team-badge alt">{match.awayTeam[0]}</span><b>{match.awayTeam}</b></div></div><div className="match-date">SEMIFINAL · {fmtDate(match.startsAt).toUpperCase()} · {new Date(match.startsAt).toLocaleTimeString('pt-BR',{hour:'2-digit',minute:'2-digit'})}</div><div className="match-place">{match.location}</div></>}
function EventsPage({events,loading,search,setSearch,onOpen}) {
 const [month,setMonth]=useState(()=>{const d=new Date();return new Date(d.getFullYear(),d.getMonth(),1)});
 const [selected,setSelected]=useState('');
 useEffect(()=>{if(!selected&&events.length){const next=[...events].filter(e=>e.status==='Publicado').sort((a,b)=>new Date(a.startsAt)-new Date(b.startsAt))[0];setSelected(dayKey(next?.startsAt||new Date()))}},[events,selected]);
 const onMonth=offset=>{const d=new Date(month.getFullYear(),month.getMonth()+offset,1);setMonth(d);setSelected(dayKey(d))};
 const updated=events.reduce((a,e)=>!a||e.updatedAt>a?e.updatedAt:a,'');
 const dayEvents=events.filter(e=>dayKey(e.startsAt)===selected&&(e.title+' '+e.location+' '+e.category).toLowerCase().includes(search.toLowerCase()));
 return <><div className="page-banner events-banner"><span className="eyebrow">AGENDA PÚBLICA</span><h1>Calendário<br/><em>de eventos.</em></h1><p>Consulte datas, locais e informações de inscrição.</p><div className="calendar-update"><RefreshCw size={18}/><span><small>ÚLTIMA ATUALIZAÇÃO DO CALENDÁRIO</small><b>{updated?'Atualizado em '+fmtDateTime(updated):'Aguardando a primeira publicação'}</b></span><span className="verified"><BadgeCheck size={13}/> Oficial</span></div><div className="event-banner-photo"><img src="/assets/culture-stage.jpg" alt="Apresentação musical no Pará"/><small className="photo-credit"><a href="https://commons.wikimedia.org/wiki/File:Festival_internacional_de_musica_do_par%C3%A1_-_panoramio.jpg" target="_blank" rel="noreferrer">Imagem de referência · Roberto de Vasconcelos</a> · <a href="https://creativecommons.org/licenses/by-sa/3.0/" target="_blank" rel="noreferrer">CC BY-SA 3.0</a></small></div></div>
  <section className="section-wrap content-section event-calendar-page">
   <div className="calendar-toolbar"><div><span className="eyebrow muted">AGENDA MUNICIPAL</span><h2>Selecione uma data</h2></div><label className="search-box"><Search size={15}/><input placeholder="Buscar evento ou local" value={search} onChange={e=>setSearch(e.target.value)}/></label></div>
   <CalendarMonth events={events} month={month} selected={selected} onSelect={setSelected} onMonth={onMonth}/>
   <div className="day-agenda-head"><div><span className="eyebrow muted">EVENTOS DO DIA</span><h2>{selected?new Intl.DateTimeFormat('pt-BR',{dateStyle:'full',timeZone:'America/Sao_Paulo'}).format(new Date(selected+'T12:00:00')):'Escolha uma data'}</h2></div><span className="index">{dayEvents.length} {dayEvents.length===1?'EVENTO':'EVENTOS'}</span></div>
   <div className="event-list">{loading?<p>Carregando agenda…</p>:dayEvents.length?dayEvents.map(e=><EventRow key={e.id} event={e} onOpen={onOpen}/>):<p className="empty-state">Nenhum evento nesta data. Toque em outro dia para consultar a agenda.</p>}</div>
   <div className="history-note"><span className="status-dot green"/><span>Eventos encerrados e cancelados continuam visíveis para consulta histórica.</span></div>
  </section></>;
}
function CalendarMonth({events,month,selected,onSelect,onMonth}) {
 const start=month.getDay(), offset=(start+6)%7, count=new Date(month.getFullYear(),month.getMonth()+1,0).getDate(), total=Math.ceil((offset+count)/7)*7;
 const cells=Array.from({length:total},(_,i)=>new Date(month.getFullYear(),month.getMonth(),i-offset+1));
 const eventDays=new Set(events.map(e=>dayKey(e.startsAt)));
 const monthText=new Intl.DateTimeFormat('pt-BR',{month:'long',year:'numeric'}).format(month);
 const label=monthText.charAt(0).toLocaleUpperCase('pt-BR')+monthText.slice(1);
 return <div className="calendar-month"><div className="month-head"><button aria-label="Mês anterior" onClick={()=>onMonth(-1)}><ChevronLeft size={18}/></button><h3>{label}</h3><button aria-label="Próximo mês" onClick={()=>onMonth(1)}><ChevronRight size={18}/></button></div><div className="calendar-weekdays">{['SEG','TER','QUA','QUI','SEX','SÁB','DOM'].map(d=><span key={d}>{d}</span>)}</div><div className="calendar-days">{cells.map((date,i)=>{const key=dayKey(date);const sameMonth=date.getMonth()===month.getMonth();return <button key={key+'-'+i} className={(sameMonth?'':'other-month')+' '+(selected===key?'selected':'')+' '+(eventDays.has(key)?'has-events':'')} onClick={()=>onSelect(key)} aria-label={new Intl.DateTimeFormat('pt-BR',{dateStyle:'full'}).format(date)}><span>{date.getDate()}</span>{eventDays.has(key)&&<i/>}</button>})}</div></div>;
}
function EventRow({event,onOpen}) {
 const status=event.status||'Publicado', canceled=status==='Cancelado', closed=status==='Encerrado';
 return <button className={'event-row '+(canceled?'event-cancelled':'')+' '+(closed?'event-closed':'')} onClick={()=>onOpen(event.id)}><span className="date-block"><b>{fmtDate(event.startsAt,{day:'2-digit'})}</b><small>{fmtDate(event.startsAt,{month:'short'}).replace('.','').toUpperCase()}</small></span><span className="event-info"><small>{event.category.toUpperCase()} · {status.toUpperCase()}</small><b>{event.title}</b><span>{new Date(event.startsAt).toLocaleTimeString('pt-BR',{hour:'2-digit',minute:'2-digit',timeZone:'America/Sao_Paulo'})} <i>·</i> {event.location}</span></span><span className="free-tag">{event.isFree?'GRATUITO':'PAGO'}</span><ChevronRight size={17} className="event-arrow"/></button>;
}
function TourismPage({places,googlePhotosEnabled}) {
 const [photos,setPhotos]=useState({});
 useEffect(()=>{if(!googlePhotosEnabled)return;let alive=true;Promise.all(places.filter(p=>p.placeId).map(async p=>{try{const meta=await api('/tourism/'+p.id+'/visual');if(alive)setPhotos(old=>({...old,[p.id]:meta}))}catch{}}));return()=>{alive=false}},[places,googlePhotosEnabled]);
 const localCredits={
  '/assets/tourism-river.jpg':['Guilherme J. Corrêa','https://commons.wikimedia.org/wiki/File:P%C3%B4r_do_Sol_em_S%C3%A3o_Miguel_do_Guama_-_panoramio.jpg','CC BY-SA 3.0'],
  '/assets/tourism-landmark.jpg':['Guilherme J. Corrêa','https://commons.wikimedia.org/wiki/File:S%C3%A3o_Miguel_do_Guam%C3%A1_-_State_of_Par%C3%A1,_Brazil_-_panoramio.jpg','CC BY-SA 3.0'],
  '/assets/tourism-church-side.jpg':['Guilherme J. Corrêa','https://commons.wikimedia.org/wiki/File:S%C3%A3o_Miguel_Arcanjo_-_panoramio_-_Guilherme_J._Corr%C3%AAa.jpg','CC BY-SA 3.0']
 };
 return <><div className="tour-intro"><div><span className="eyebrow">PONTOS DE INTERESSE</span><h1>Conheça os<br/><em>lugares da cidade.</em></h1><p>Fotos, informações e localização para abrir no Maps.</p></div><div className="tour-count"><b>{String(places.length).padStart(2,'0')}</b><span>LUGARES<br/>CADASTRADOS</span></div></div><section className="section-wrap gallery-section"><div className="gallery-head"><span className="eyebrow muted">LAZER E TURISMO</span><span>{String(places.length).padStart(2,'0')} <i>·</i> LUGARES</span></div><div className="masonry">{places.map((p,i)=>{const photo=photos[p.id];let fallback=p.imageUrl||((i%2)?'/assets/tourism-landmark.jpg':'/assets/tourism-river.jpg');if(p.name.includes('Praça')||p.name.includes('Mercado'))fallback='/assets/tourism-landmark.jpg';if(p.name.includes('Centro Histórico'))fallback='/assets/tourism-church-side.jpg';const credit=localCredits[fallback]||localCredits['/assets/tourism-river.jpg'];const image=photo?.photoName?'/api/tourism/'+p.id+'/photo?name='+encodeURIComponent(photo.photoName):fallback;return <article className={'place-card place-'+(i%6+1)} key={p.id}><div className="place-photo"><img src={image} alt={p.name} loading="lazy" onError={e=>{e.currentTarget.src=fallback}}/><span className="place-category">{p.category}</span></div><div className="place-copy"><span className="place-index">{String(i+1).padStart(2,'0')} / PONTO TURÍSTICO</span><h2 className="place-title">{p.name}</h2><p className="place-caption">{p.description}</p><span className="place-address"><MapPin size={14}/>{p.address||'Endereço não cadastrado'}</span><div className="place-card-foot"><a className="map-link" href={mapHref(p)} target="_blank" rel="noreferrer"><Map size={15}/> Abrir no Maps <ExternalLink size={12}/></a>{photo?<small className="photo-credit"><a href={photo.sourceUrl} target="_blank" rel="noreferrer">Foto: Google Maps</a>{photo.authorAttributions?.map(x=><span key={x.displayName}>{x.uri?<a href={x.uri} target="_blank" rel="noreferrer">{x.displayName}</a>:x.displayName}</span>)}</small>:<small className="photo-credit"><a href={credit[1]} target="_blank" rel="noreferrer">Foto: {credit[0]}</a> · <a href={credit[2].endsWith("3.0")?"https://creativecommons.org/licenses/by-sa/3.0/":"https://creativecommons.org/licenses/by-sa/4.0/"} target="_blank" rel="noreferrer">{credit[2]}</a></small>}</div></div></article>})}</div>{!places.length&&<p className="empty-state">Ainda não há pontos turísticos publicados.</p>}<div className="tour-note"><MapPin size={18}/><span>O botão abre a localização em um aplicativo de mapas compatível.</span></div></section></>;
}
function LoginPage({onSubmit}){return <main className="login-page"><section className="login-card"><BrandMark/><span className="eyebrow muted">ACESSO INSTITUCIONAL</span><h1>Bem-vindo ao<br/>painel SECELT.</h1><p>Entre com sua conta de servidor para administrar conteúdos e a agenda oficial.</p><LoginFields onSubmit={onSubmit}/><a className="back-link" href="#" onClick={e=>{e.preventDefault();location.hash='';location.reload()}}>← Voltar ao início</a></section><div className="login-art"><Art kind="hero-land"/></div></main>}
function LoginForm({onSubmit}){return <div className="login-modal-content"><span className="eyebrow green-text">ÁREA ADMINISTRATIVA</span><h2>Acesse sua conta</h2><p>Entre com suas credenciais institucionais para continuar.</p><LoginFields onSubmit={onSubmit}/></div>}
function LoginFields({onSubmit}){return <form className="login-form" onSubmit={onSubmit}><label>E-mail institucional<input name="email" type="email" autoComplete="username" defaultValue="admin@secelt.local" required/></label><label>Senha<input name="password" type="password" autoComplete="current-password" defaultValue="Guama#2026" required/></label><button className="button blue full">Entrar no painel <ChevronRight size={16}/></button></form>}
function AdminPage({theme,user,overview,events,places,onCreate,onCreatePlace,onCreateUser,onEdit,onEditPlace,onStatus,onPlaceStatus,onLogout,onRefresh}) {
 const isAdmin=user.role==='Administrador Geral';
 const [tab,setTab]=useState('Resumo'),[filter,setFilter]=useState('Todos'),[selectedDate,setSelectedDate]=useState(''),[month,setMonth]=useState(()=>{const d=new Date();return new Date(d.getFullYear(),d.getMonth(),1)});
 const queue=events.filter(e=>e.status==='Aguardando Aprovação');
 const filtered=events.filter(e=>(filter==='Todos'||e.status===filter)&&(!selectedDate||dayKey(e.startsAt)===selectedDate));
 const tabs=[['Resumo',LayoutDashboard],['Eventos',CalendarDays],['Turismo',MapPin],['Esporte',Trophy],['Equipe',Users],...(isAdmin?[['Inscrições',QrCode],['Servidores',Users]]:[])];
 const monthMove=direction=>{setMonth(new Date(month.getFullYear(),month.getMonth()+direction,1));setSelectedDate('')};
 return <div className="admin-layout"><aside className="admin-sidebar"><div className="admin-logo"><BrandMark/><span><b>SECELT</b><small>PAINEL DE GESTÃO</small></span></div><small className="side-label">GESTÃO DE CONTEÚDO</small>{tabs.map(([name,I])=><button key={name} className={'side-link '+(tab===name?'chosen':'')} onClick={()=>setTab(name)}><I size={16}/>{name}{name==='Eventos'&&<i>{events.length}</i>}</button>)}<div className="sidebar-bottom"><span className="avatar">{user.name.split(' ').map(s=>s[0]).slice(0,2).join('')}</span><span><b>{user.name}</b><small>{user.role}</small></span><button title="Sair" onClick={onLogout}><LogOut size={15}/></button></div></aside>
  <section className="admin-main"><header className="admin-top"><div><span className="eyebrow muted">ADMINISTRAÇÃO</span><h1>{tab==='Resumo'?'Visão geral':tab}</h1></div><button className="admin-profile" onClick={onRefresh}><span className="avatar">{user.name.split(' ').map(s=>s[0]).slice(0,2).join('')}</span>{user.name}<RefreshCw size={13}/></button></header>
   {tab==='Resumo'?<><div className="welcome-row"><div><h2>Olá, {user.name.split(' ')[0]}</h2><p>Conteúdos e agenda atualizados no banco do projeto.</p></div><div className="admin-actions"><Button onClick={onCreate}><Plus size={15}/> Novo evento</Button><button className="button outline" onClick={onCreatePlace}><MapPin size={14}/> Novo ponto</button></div></div>
    <div className="stat-grid"><span className="liquid-scene stat-scene" aria-hidden="true"/>{[['AGUARDANDO APROVAÇÃO',String(overview.pending).padStart(2,'0'),'Requer revisão',Clock3,'amber'],['EVENTOS PUBLICADOS',String(overview.published).padStart(2,'0'),'Visíveis na agenda',FileText,'blue'],['PONTOS TURÍSTICOS',String(places.filter(p=>p.status==='Publicado').length).padStart(2,'0'),'Na galeria pública',MapPin,'green']].map(([title,value,caption,Icon,color])=><article className="stat-card liquid-target" data-config={glassConfig(theme,'tile')} key={title}><span>{title}</span><b>{value}</b><small><i className={`status-dot ${color==='amber'?'amber':'green'}`}/>{caption}</small><Icon className={`stat-icon ${color}-icon`} size={18}/></article>)}</div>
    <div className="admin-columns"><article className="admin-panel queue-panel"><div className="admin-panel-head"><div><h3>Fila de aprovação</h3><p>Eventos enviados para revisão</p></div><span className="queue-count">{String(queue.length).padStart(2,'0')} PENDENTES</span></div>{queue.length?queue.slice(0,4).map(e=><ApprovalItem key={e.id} event={e} isAdmin={isAdmin} onStatus={onStatus}/>):<div className="empty-inline"><BadgeCheck size={19}/>A fila está vazia.</div>}<button className="text-link queue-link" onClick={()=>setTab('Eventos')}>Abrir eventos →</button></article>
     <article className="admin-panel calendar-panel"><div className="admin-panel-head"><div><h3>Calendário oficial</h3><p>Atualização mais recente</p></div><CalendarDays className="calendar-icon"/></div><div className="calendar-last"><span className="status-dot green"/><b>{overview.calendarUpdated?'Agenda atualizada':'Aguardando publicação'}</b></div><strong>{fmtDateTime(overview.calendarUpdated)||'—'}</strong><p>{events.filter(e=>e.status==='Publicado').length} eventos disponíveis ao público.</p><button className="button outline full" onClick={()=>setTab('Eventos')}>Abrir calendário <ChevronRight size={14}/></button></article></div>
    <AdminTable events={events.slice(0,5)} onStatus={onStatus} onEdit={onEdit} isEditor={!isAdmin} isAdmin={isAdmin}/>
   </>:tab==='Eventos'?<><div className="welcome-row"><div><h2>Agenda e calendário</h2><p>Selecione uma data para filtrar os registros e editar o calendário.</p></div><Button onClick={onCreate}><Plus size={15}/> Novo evento</Button></div>
    <div className="admin-calendar"><div className="admin-calendar-head"><div><b>Calendário de gestão</b><small>{selectedDate?'Filtrado por '+new Intl.DateTimeFormat('pt-BR',{dateStyle:'long'}).format(new Date(selectedDate+'T12:00:00')):'Toque em uma data para filtrar a tabela'}</small></div>{selectedDate&&<button className="text-link" onClick={()=>setSelectedDate('')}>Limpar data</button>}</div><CalendarMonth events={events} month={month} selected={selectedDate} onSelect={setSelectedDate} onMonth={monthMove}/></div>
    <div className="table-toolbar"><div className="filter-chips">{['Todos','Rascunho','Aguardando Aprovação','Publicado','Reprovado','Encerrado','Cancelado'].map(s=><button className={filter===s?'selected':''} key={s} onClick={()=>setFilter(s)}>{s}</button>)}</div></div><AdminTable events={filtered} onStatus={onStatus} onEdit={onEdit} isEditor={!isAdmin} isAdmin={isAdmin}/>
   </>:tab==='Turismo'?<TourismAdmin places={places} isAdmin={isAdmin} onCreate={onCreatePlace} onEdit={onEditPlace} onStatus={onPlaceStatus}/>:tab==='Esporte'?<SportsAdmin sportsMode/>:tab==='Inscrições'?<RegistrationAdmin events={events} token={localStorage.getItem('secelt-token')}/>:tab==='Servidores'?<UserAdmin token={localStorage.getItem('secelt-token')} onCreate={onCreateUser}/>:<TeamAdmin token={localStorage.getItem('secelt-token')}/>}
  </section></div>;
}
function ApprovalItem({event,isAdmin,onStatus}){return <div className="approval-item"><div className="approval-thumb"><Art kind="admin-art a1"/></div><div className="approval-details"><span className="content-type">{event.category.toUpperCase()} · {fmtDate(event.startsAt).toUpperCase()}</span><b>{event.title}</b><small>{event.location} · {fmtDateTime(event.updatedAt)}</small></div><span className="pending-tag">Aguardando</span><div className="approval-actions">{isAdmin?<><button className="approve" onClick={()=>onStatus(event.id,'Publicado')}><Check size={12}/> Aprovar</button><button className="reject" onClick={()=>onStatus(event.id,'Reprovado')}><X size={12}/> Devolver</button></>:<span className="role-note">Somente Administrador Geral publica</span>}</div></div>}
function AdminTable({events,onStatus,onEdit,isEditor,isAdmin}){return <article className="admin-panel table-panel"><div className="admin-panel-head"><div><h3>Agenda e conteúdos</h3><p>Registros salvos no sistema</p></div><span className="queue-count">{events.length} REGISTROS</span></div><div className="table-scroll"><table><thead><tr><th>EVENTO</th><th>MÓDULO</th><th>LOCAL</th><th>DATA</th><th>STATUS</th><th>AÇÃO</th></tr></thead><tbody>{events.map(e=><tr key={e.id}><td><b>{e.title}</b></td><td>{e.category}</td><td>{e.location}</td><td>{fmtDateTime(e.startsAt)}</td><td><StatusTag status={e.status}/></td><td className="row-actions">{['Rascunho','Reprovado'].includes(e.status)&&<><button className="submit-review" onClick={()=>onEdit(e.id)}><Pencil size={11}/> Ajustar</button><button className="submit-review" onClick={()=>onStatus(e.id,'Aguardando Aprovação')}>Enviar à fila</button></>}{e.status==='Aguardando Aprovação'&&isAdmin&&<><button className="approve mini-action" onClick={()=>onStatus(e.id,'Publicado')}>Aprovar</button><button className="reject mini-action" onClick={()=>onStatus(e.id,'Reprovado')}>Devolver</button></>}{e.status==='Publicado'&&isAdmin&&<><button className="submit-review" onClick={()=>onEdit(e.id)}><Pencil size={11}/> Editar</button><button className="mini-action" onClick={()=>onStatus(e.id,'Encerrado')}>Encerrar</button><button className="reject mini-action" onClick={()=>onStatus(e.id,'Cancelado')}>Cancelar</button></>}</td></tr>)}</tbody></table>{!events.length&&<p className="empty-state">Nenhum evento encontrado neste filtro.</p>}</div></article>}
function SportsAdmin({sportsMode}){return <article className="admin-panel table-panel"><div className="admin-panel-head"><div><h3>Competições municipais</h3><p>Equipes, participantes e partidas cadastradas no banco local</p></div></div><table><thead><tr><th>COMPETIÇÃO</th><th>MODALIDADE</th><th>EDIÇÃO</th><th>STATUS</th></tr></thead><tbody><tr><td>Campeonato Municipal</td><td>Futebol</td><td>2026</td><td>Em andamento</td></tr><tr><td>Jogos Guamaenses</td><td>Futebol</td><td>2026</td><td>Em andamento</td></tr><tr><td>Jogos Escolares</td><td>Futsal</td><td>2026</td><td>Planejada</td></tr></tbody></table></article>}
function RegistrationAdmin({events,token}){const [list,setList]=useState([]);const [selected,setSelected]=useState('');useEffect(()=>{if(selected)api(`/admin/events/${selected}/registrations`,{token}).then(d=>setList(d.items)).catch(()=>setList([]))},[selected,token]);const eligible=events.filter(e=>e.status==='Publicado');return <article className="admin-panel table-panel"><div className="admin-panel-head"><div><h3>Inscrições por evento</h3><p>Lista de inscritos para controle demonstrativo</p></div><select className="filter-select" value={selected} onChange={e=>setSelected(e.target.value)}><option value="">Selecione um evento</option>{eligible.map(e=><option value={e.id} key={e.id}>{e.title}</option>)}</select></div><table><thead><tr><th>NOME</th><th>E-MAIL</th><th>DATA DA INSCRIÇÃO</th><th>CHECK-IN</th></tr></thead><tbody>{list.map(r=><tr key={r.id}><td>{r.name}</td><td>{r.email}</td><td>{fmtDateTime(r.createdAt)}</td><td>{r.checkinStatus}</td></tr>)}</tbody></table>{selected&&!list.length&&<p className="empty-state">Ainda não há inscrições para este evento.</p>}</article>}
function StatusTag({status}){const c=status==='Publicado'?'published-tag':status==='Aguardando Aprovação'?'pending-tag':['Reprovado'].includes(status)?'rejected-tag':['Encerrado','Cancelado','Arquivado'].includes(status)?'closed-tag':'draft-tag';return <span className={c}>{status}</span>}
function TeamAdmin({token}){const [items,setItems]=useState([]);useEffect(()=>{api('/admin/teams',{token}).then(d=>setItems(d.items)).catch(()=>{})},[token]);return <article className="admin-panel table-panel"><div className="admin-panel-head"><div><h3>Equipes e competições</h3><p>Composição esportiva cadastrada</p></div></div><table><thead><tr><th>EQUIPE</th><th>COMPETIÇÃO</th><th>TÉCNICO</th></tr></thead><tbody>{items.map(x=><tr key={x.id}><td>{x.name}</td><td>{x.competition}</td><td>{x.coach}</td></tr>)}</tbody></table></article>}
function UserAdmin({token,onCreate}){const [users,setUsers]=useState([]);const [loading,setLoading]=useState(true);const refresh=()=>api('/admin/users',{token}).then(d=>setUsers(d.items)).catch(()=>setUsers([])).finally(()=>setLoading(false));useEffect(()=>{refresh()},[token]);return <article className="admin-panel table-panel"><div className="admin-panel-head"><div><h3>Contas de servidores</h3><p>Acesso institucional por perfil e princípio de menor privilégio</p></div><Button onClick={onCreate}><Plus size={14}/> Nova conta</Button></div><div className="table-scroll"><table><thead><tr><th>SERVIDOR</th><th>E-MAIL</th><th>PERFIL</th><th>ACESSO</th></tr></thead><tbody>{users.map(u=><tr key={u.id}><td><b>{u.name}</b></td><td>{u.email}</td><td>{u.role}</td><td>{u.active?'Ativo':'Inativo'}</td></tr>)}</tbody></table>{loading&&<p className="empty-state">Carregando contas…</p>}</div></article>}

function EventDetails({event,onRegister}) {
 const [registering,setRegistering]=useState(false);
 const isCancelled=event.status==='Cancelado',isClosed=event.status==='Encerrado',canRegister=event.status==='Publicado'&&event.isFree;
 const submit=e=>{e.preventDefault();const data=new FormData(e.currentTarget);onRegister(data.get('name'),data.get('email'))};
 return <div className="event-details"><span className="eyebrow green-text">{event.category} · {event.status}</span><h2>{event.title}</h2><p>{event.description||'Informações publicadas pela organização do evento.'}</p>
  <div className="detail-grid"><div><small>DATA E HORÁRIO</small><b>{fmtDateTime(event.startsAt)}</b></div><div><small>LOCAL</small><b>{event.location}</b></div><div><small>FAIXA ETÁRIA</small><b>{event.ageRange||'Livre'}</b></div><div><small>ORGANIZAÇÃO</small><b>{event.organizerType||'SECELT'}</b></div><div><small>ENTRADA</small><b>{event.isFree?'Gratuita':'Paga'}</b></div><div><small>REGRA DE BEBIDA</small><b>{event.drinkRule||'Não informado'}</b></div></div>
  {isCancelled&&<p className="event-status-note canceled-note">Este evento foi cancelado. A informação permanece no calendário oficial.</p>}
  {isClosed&&<p className="event-status-note">Este evento foi encerrado. Consulte o histórico da agenda.</p>}
  {!event.isFree&&<p className="event-status-note">O app não oferece pagamento ou checkout. Consulte a organização para detalhes.</p>}
  {canRegister&&!registering&&<button className="button green-button full" onClick={()=>setRegistering(true)}>Inscrever-se e gerar QR Code <QrCode size={16}/></button>}
  {registering&&canRegister&&<form className="register-form" onSubmit={submit}><label>Nome completo<input name="name" autoComplete="name" required maxLength="120"/></label><label>E-mail<input name="email" type="email" autoComplete="email" required maxLength="200"/></label><div className="form-actions"><button type="button" className="button outline" onClick={()=>setRegistering(false)}>Voltar</button><button className="button green-button" type="submit">Gerar ingresso <QrCode size={15}/></button></div></form>}
 </div>;
}
function Ticket({event,qr}) {
 return <div className="ticket-modal"><span className="eyebrow green-text">INSCRIÇÃO CONFIRMADA</span><h2>Ingresso digital</h2><p>{event.title}</p><div className="ticket-code"><QRCodeSVG value={qr} size={204} level="M" includeMargin/></div><b>{fmtDateTime(event.startsAt)}</b><small>{event.location}</small><p>Apresente este código na entrada do evento.</p></div>;
}
function PlaceForm({event,token,onSubmit,googlePhotosEnabled}) {
 const [query,setQuery]=useState(''),[results,setResults]=useState([]),[searching,setSearching]=useState(false),[feedback,setFeedback]=useState('');
 const [placeId,setPlaceId]=useState(event?.placeId||'');
 const searchPlaces=async()=>{setSearching(true);setFeedback('');try{const result=await api('/admin/maps/places?q='+encodeURIComponent(query),{token});setResults(result.items);if(!result.items.length)setFeedback('Nenhum local encontrado.');}catch(e){setFeedback(e.message)}finally{setSearching(false)}};
 return <div className="form-modal"><span className="eyebrow green-text">PONTOS TURÍSTICOS</span><h2>{event?'Editar ponto turístico':'Cadastrar ponto turístico'}</h2><p>O conteúdo começa como rascunho e passa pela fila de aprovação.</p>
  <div className="maps-place-search"><label>Associar fotos do Google Maps<input value={query} onChange={e=>setQuery(e.target.value)} placeholder="Ex.: Balneário do Guamá" disabled={!googlePhotosEnabled}/></label><button type="button" className="button outline" onClick={searchPlaces} disabled={!googlePhotosEnabled||searching||query.trim().length<3}>{searching?'Buscando…':'Buscar local'}</button>{googlePhotosEnabled?<small>Escolha um Place ID. Nome e endereço precisam ser conferidos e digitados abaixo.</small>:<small>Busca desligada no servidor. Ative Places API para associar fotos; as imagens locais seguem disponíveis.</small>}{feedback&&<p className="search-feedback">{feedback}</p>}{results.map(result=><button type="button" className={'place-search-result '+(placeId===result.placeId?'active':'')} key={result.placeId} onClick={()=>{setPlaceId(result.placeId);setFeedback('Local associado. Confira e digite manualmente o nome e o endereço abaixo.')}}><b>{result.suggestion}</b><span>{result.addressSuggestion}</span><small>{placeId===result.placeId?'Associado':'Usar Place ID'}</small></button>)}</div>
  <form className="event-form" onSubmit={onSubmit}><input type="hidden" name="placeId" value={placeId}/><label>Nome do local<input name="name" defaultValue={event?.name||''} required maxLength="140"/></label><label>Descrição<textarea name="description" defaultValue={event?.description||''} placeholder="O que a pessoa vai encontrar neste local"/></label><div className="form-row"><label>Categoria<select name="category" defaultValue={event?.category||'Lazer'}><option>Balneário</option><option>Praça</option><option>Lazer</option><option>Cultura</option><option>Natureza</option><option>História</option></select></label><label>Imagem local<select name="imageUrl" defaultValue={event?.imageUrl||'/assets/tourism-river.jpg'}><option value="/assets/tourism-river.jpg">Rio Guamá</option><option value="/assets/tourism-landmark.jpg">Igreja Matriz</option><option value="/assets/tourism-church-side.jpg">Monumento São Miguel Arcanjo</option></select></label></div><label>Endereço conferido<input name="address" defaultValue={event?.address||''} placeholder="Informe um endereço ou referência" required maxLength="220"/></label><div className="form-row"><label>Latitude<input name="latitude" type="number" step="any" defaultValue={event?.latitude??''}/></label><label>Longitude<input name="longitude" type="number" step="any" defaultValue={event?.longitude??''}/></label></div><div className="form-actions"><button type="button" className="button outline" onClick={()=>document.dispatchEvent(new Event('close-dialog'))}>Cancelar</button><button className="button blue" type="submit">{event?'Salvar rascunho':'Criar rascunho'} <ChevronRight size={15}/></button></div></form>
 </div>;
}
function TourismAdmin({places,isAdmin,onCreate,onEdit,onStatus}) {
 const action=p=><div className="row-actions">{['Rascunho','Reprovado'].includes(p.status)&&<><button className="submit-review" onClick={()=>onEdit(p.id)}><Pencil size={11}/> Ajustar</button><button className="submit-review" onClick={()=>onStatus(p.id,'Aguardando Aprovação')}>Enviar à fila</button></>}{p.status==='Aguardando Aprovação'&&isAdmin&&<><button className="approve mini-action" onClick={()=>onStatus(p.id,'Publicado')}>Publicar</button><button className="reject mini-action" onClick={()=>onStatus(p.id,'Reprovado')}>Devolver</button></>}{p.status==='Publicado'&&isAdmin&&<><button className="submit-review" onClick={()=>onEdit(p.id)}><Pencil size={11}/> Editar</button><button className="reject mini-action" onClick={()=>onStatus(p.id,'Arquivado')}>Arquivar</button></>}</div>;
 return <><div className="welcome-row"><div><h2>Locais da galeria</h2><p>O editor envia rascunhos; o Administrador Geral publica na área pública.</p></div><button className="button blue" onClick={onCreate}><Plus size={15}/> Novo ponto turístico</button></div><article className="admin-panel table-panel"><div className="admin-panel-head"><div><h3>Pontos turísticos e de lazer</h3><p>Cadastros salvos no SQLite</p></div><span className="queue-count">{places.length} LOCAIS</span></div><div className="table-scroll"><table><thead><tr><th>LOCAL</th><th>CATEGORIA</th><th>ENDEREÇO</th><th>ATUALIZADO</th><th>STATUS</th><th>AÇÃO</th></tr></thead><tbody>{places.map(p=><tr key={p.id}><td><b>{p.name}</b></td><td>{p.category}</td><td>{p.address}</td><td>{fmtDateTime(p.updatedAt)}</td><td><StatusTag status={p.status}/></td><td>{action(p)}</td></tr>)}</tbody></table>{!places.length&&<p className="empty-state">Nenhum ponto turístico cadastrado.</p>}</div></article></>;
}

function UserForm({onSubmit}){return <div className="form-modal"><span className="eyebrow green-text">ACESSO INSTITUCIONAL</span><h2>Nova conta de servidor.</h2><p>Defina um perfil compatível com a função do servidor na SECELT.</p><form className="event-form" onSubmit={onSubmit}><label>Nome completo<input name="name" required maxLength="120"/></label><label>E-mail institucional<input name="email" type="email" required maxLength="200"/></label><label>Perfil<select name="role"><option>Editor SECELT</option><option>Administrador Geral</option></select></label><label>Senha temporária<input name="password" type="password" minLength="10" required/></label><div className="form-actions"><Button type="submit">Criar conta <ChevronRight size={15}/></Button></div></form></div>}
function EventFormModal({children,onClose,theme}){useEffect(()=>{const h=()=>onClose();document.addEventListener('close-dialog',h);return()=>document.removeEventListener('close-dialog',h)},[onClose]);return <div className="modal-scrim" onMouseDown={e=>e.target===e.currentTarget&&onClose()}><span className="liquid-scene modal-scene" aria-hidden="true"/><section className="event-modal liquid-sheet liquid-target" data-config={glassConfig(theme,'sheet')} role="dialog" aria-modal="true"><button className="modal-close" onClick={onClose}><X/></button>{children}</section></div>}
function Modal({children,onClose,theme}){return <EventFormModal theme={theme} onClose={onClose}>{children}</EventFormModal>}if('serviceWorker' in navigator)window.addEventListener('load',()=>navigator.serviceWorker.register('/sw.js').catch(()=>{}));





class AppBoundary extends React.Component{constructor(props){super(props);this.state={error:null}}static getDerivedStateFromError(error){return {error}}componentDidCatch(error){console.error(error)}render(){if(this.state.error)return <main style={{padding:24,fontFamily:'Arial',color:'#26384a'}}><h1>Não foi possível abrir esta área</h1><p>{this.state.error.message}</p><button onClick={()=>location.reload()}>Tentar novamente</button></main>;return this.props.children}}
createRoot(document.getElementById('root')).render(<AppBoundary><App/></AppBoundary>);



